"""Model providers: chat models, embeddings, and the cross-encoder.

Everything that talks to a model goes through this module. The point is that
the retrieval and graph code never names a vendor, so swapping Ollama for
OpenAI is a config change rather than an edit to six files.

Defaults are local (Ollama + a sentence-transformers embedding model) for three
reasons worth defending:

* Reproducibility. Every number in results/ can be regenerated by anyone who
  clones the repo, with no key and no bill. An eval suite nobody can re-run is
  not much of an eval suite.
* Cost. The Phase B/C sweeps embed the corpus under 9 chunking schemes and run
  the full question set 30+ times. On a hosted embedding API that is real money
  for a portfolio project.
* Honesty about the ceiling. A 3B generator is a weak model. Measuring on it
  makes retrieval improvements *harder* to fake: a big model can paper over bad
  retrieval by knowing the answer already, and these papers are famous enough
  that a large model has memorised them.

The loaders are cached because loading MiniLM from disk on every call would
dominate sweep runtime.
"""

from __future__ import annotations

import functools
import logging
import os
import time

from langchain_core.cross_encoders import BaseCrossEncoder
from langchain_core.embeddings import Embeddings
from langchain_core.language_models import BaseChatModel

from auralith.config import Settings

log = logging.getLogger(__name__)


class ProviderError(RuntimeError):
    """Raised when a model backend is unreachable or misconfigured.

    `retryable` is False for errors a retry cannot fix (bad key, bad request).
    """

    def __init__(self, message: str = "", retryable: bool = True) -> None:
        super().__init__(message)
        self.retryable = retryable


# fastembed's ONNX export of the same cross-encoder weights.
_ONNX_CROSS_ENCODERS = {
    "cross-encoder/ms-marco-MiniLM-L-6-v2": "Xenova/ms-marco-MiniLM-L-6-v2",
}


def _onnx_threads() -> int | None:
    return int(os.getenv("AURALITH_ONNX_THREADS", "0")) or None


class _OnnxEmbeddings(Embeddings):
    """fastembed (ONNX) embeddings; same model, pooling and L2 norm as the torch path."""

    def __init__(self, model) -> None:
        self._model = model

    def embed_documents(self, texts: list[str]) -> list[list[float]]:
        return [v.tolist() for v in self._model.embed(texts, batch_size=8)]

    def embed_query(self, text: str) -> list[float]:
        return self.embed_documents([text])[0]


_GEMINI_API = "https://generativelanguage.googleapis.com/v1beta"
_GEMINI_DIM = 768
_GEMINI_BATCH = 32
_GEMINI_TRIES = 6


class _GeminiEmbeddings(Embeddings):
    """Gemini embeddings over REST: no local model, so the host needs no ML stack."""

    def __init__(self, model: str, api_key: str, timeout: float) -> None:
        self._model, self._key, self._timeout = model, api_key, min(timeout, 30)

    def _post(self, texts: list[str], task: str, tries: int = _GEMINI_TRIES) -> list[list[float]]:
        import httpx

        body = {
            "requests": [
                {
                    "model": f"models/{self._model}",
                    "content": {"parts": [{"text": t}]},
                    "taskType": task,
                    "outputDimensionality": _GEMINI_DIM,
                }
                for t in texts
            ]
        }
        url = f"{_GEMINI_API}/models/{self._model}:batchEmbedContents"
        for attempt in range(tries):
            try:
                r = httpx.post(
                    url, json=body, headers={"x-goog-api-key": self._key},
                    timeout=self._timeout,
                )
            except httpx.TransportError as exc:
                # httpx messages carry the URL, never the header, so the key stays out.
                r, err = None, type(exc).__name__
            else:
                if r.status_code == 200:
                    vals = [e["values"] for e in r.json()["embeddings"]]
                    if len(vals) != len(texts):
                        raise ProviderError(
                            f"Gemini returned {len(vals)} embeddings for {len(texts)} inputs."
                        )
                    return vals
                err = f"HTTP {r.status_code}"
                if r.status_code != 429 and r.status_code < 500:
                    raise ProviderError(
                        f"Gemini embeddings rejected the request ({err}): check "
                        "GEMINI_API_KEY and AURALITH_EMBEDDING_MODEL.",
                        retryable=False,
                    )
            delay = min(2.0 ** (attempt + 1), 60.0)
            if r is not None and (ra := r.headers.get("Retry-After", "")).isdigit():
                delay = min(float(ra), 60.0)
            if attempt < tries - 1:
                log.warning("Gemini embeddings %s; retrying in %.0fs", err, delay)
                time.sleep(delay)
        raise ProviderError(f"Gemini embeddings unavailable after retries ({err}).")

    def _embed(
        self, texts: list[str], task: str, tries: int = _GEMINI_TRIES
    ) -> list[list[float]]:
        out: list[list[float]] = []
        for i in range(0, len(texts), _GEMINI_BATCH):
            for v in self._post(texts[i : i + _GEMINI_BATCH], task, tries):
                n = sum(x * x for x in v) ** 0.5 or 1.0
                out.append([x / n for x in v])  # Chroma/pgvector rank by L2
        return out

    def embed_documents(self, texts: list[str]) -> list[list[float]]:
        return self._embed(texts, "RETRIEVAL_DOCUMENT")

    def embed_query(self, text: str) -> list[float]:
        # Few tries: /ask falls back to BM25 rather than stalling on a quota wait.
        return self._embed([text], "RETRIEVAL_QUERY", tries=2)[0]


class _OnnxCrossEncoder(BaseCrossEncoder):
    def __init__(self, model) -> None:
        self._model = model

    def score(self, text_pairs: list[tuple[str, str]]) -> list[float]:
        return list(self._model.rerank_pairs(text_pairs, batch_size=8))


class _PassThroughCrossEncoder(BaseCrossEncoder):
    """Keeps retrieval order: reranking off for hosts that cannot run a cross-encoder."""

    def score(self, text_pairs: list[tuple[str, str]]) -> list[float]:
        return [-float(i) for i in range(len(text_pairs))]


@functools.lru_cache(maxsize=4)
def get_embeddings(settings: Settings) -> Embeddings:
    """Return the embedding model.

    Local sentence-transformers by default. `normalize_embeddings=True` matters:
    MiniLM is trained for cosine similarity, and Chroma's default space is L2.
    Normalising makes L2 distance a monotone function of cosine similarity, so
    the ranking Chroma returns is the ranking the model intends. Getting this
    wrong degrades retrieval quietly, with no error.
    """
    if settings.provider == "openai":
        if not settings.openai_api_key:
            raise ProviderError(
                "AURALITH_PROVIDER=openai but OPENAI_API_KEY is not set. "
                "Export it or set AURALITH_PROVIDER=ollama."
            )
        from langchain_openai import OpenAIEmbeddings

        return OpenAIEmbeddings(
            model="text-embedding-3-small", api_key=settings.openai_api_key
        )

    if settings.embedding_provider == "gemini":
        if not settings.gemini_api_key:
            raise ProviderError("AURALITH_EMBEDDING_PROVIDER=gemini but GEMINI_API_KEY is not set.")
        emb: Embeddings = _GeminiEmbeddings(
            settings.embedding_model, settings.gemini_api_key, settings.request_timeout
        )
        if cache := os.getenv("AURALITH_EMBED_CACHE"):  # eval reruns: don't re-spend quota
            from pathlib import Path

            from langchain_classic.embeddings import CacheBackedEmbeddings
            from langchain_classic.storage import LocalFileStore

            emb = CacheBackedEmbeddings.from_bytes_store(
                emb,
                LocalFileStore(Path(cache) / "doc"),
                namespace=f"{settings.embedding_model}-{_GEMINI_DIM}",
                query_embedding_cache=LocalFileStore(Path(cache) / "query"),
                key_encoder="sha256",
            )
        return emb

    if settings.ml_backend == "onnx":
        from fastembed import TextEmbedding

        log.info("Loading ONNX embedding model: %s", settings.embedding_model)
        return _OnnxEmbeddings(
            TextEmbedding(
                settings.embedding_model, threads=_onnx_threads(), enable_cpu_mem_arena=False
            )
        )

    from langchain_huggingface import HuggingFaceEmbeddings

    log.info("Loading local embedding model: %s", settings.embedding_model)
    return HuggingFaceEmbeddings(
        model_name=settings.embedding_model,
        model_kwargs={"device": "cpu"},
        encode_kwargs={"normalize_embeddings": True},
    )


@functools.lru_cache(maxsize=8)
def get_chat_model(settings: Settings, model: str | None = None) -> BaseChatModel:
    """Return a chat model. `model` overrides the configured generator."""
    name = model or settings.generator_model

    # Only the generator model goes hosted; any other explicit `model=` (the
    # judge) stays on Ollama.
    if settings.generator_provider == "gemini" and model in (None, settings.generator_model):
        if not settings.gemini_api_key:
            raise ProviderError("AURALITH_GENERATOR_PROVIDER=gemini but GEMINI_API_KEY is not set.")
        from langchain_openai import ChatOpenAI

        return ChatOpenAI(
            model=name,
            temperature=settings.temperature,
            api_key=settings.gemini_api_key,
            base_url="https://generativelanguage.googleapis.com/v1beta/openai/",
            timeout=settings.request_timeout,
            max_tokens=settings.max_output_tokens,
            max_retries=6,  # free tier 429s; SDK backs off
        )

    if settings.provider == "openai":
        if not settings.openai_api_key:
            raise ProviderError(
                "AURALITH_PROVIDER=openai but OPENAI_API_KEY is not set."
            )
        from langchain_openai import ChatOpenAI

        return ChatOpenAI(
            model=name,
            temperature=settings.temperature,
            api_key=settings.openai_api_key,
            timeout=settings.request_timeout,
        )

    from langchain_ollama import ChatOllama

    return ChatOllama(
        model=name,
        temperature=settings.temperature,
        base_url=settings.ollama_base_url,
        # See Settings.max_output_tokens. Uniform across configs, so it cannot
        # bias a comparison.
        num_predict=settings.max_output_tokens,
        client_kwargs={"timeout": settings.request_timeout},
    )


def get_judge_model(settings: Settings) -> BaseChatModel:
    """The LLM-as-judge.

    Deliberately a *different, larger* model than the generator. A model
    grading its own output is measurably self-favouring; using qwen2.5:7b to
    grade llama3.2:3b removes the most obvious form of that bias. It does not
    remove all of it, which is why judge agreement is validated against hand
    labels in eval/judge.py rather than assumed.
    """
    return get_chat_model(settings, model=settings.judge_model)


@functools.lru_cache(maxsize=2)
def get_cross_encoder(settings: Settings):
    """Cross-encoder used for Phase C reranking.

    Runs locally via sentence-transformers. Unlike the bi-encoder used for
    indexing, this scores (query, passage) jointly, so it cannot be precomputed
    and is the expensive part of the pipeline.
    """
    if settings.rerank_provider == "none":
        return _PassThroughCrossEncoder()
    if settings.rerank_provider != "local":
        raise ProviderError(
            f"Unknown rerank_provider {settings.rerank_provider!r} (use 'local' or 'none')."
        )
    if settings.ml_backend == "onnx":
        from fastembed.rerank.cross_encoder import TextCrossEncoder

        name = _ONNX_CROSS_ENCODERS.get(
            settings.cross_encoder_model, settings.cross_encoder_model
        )
        log.info("Loading ONNX cross-encoder: %s", name)
        return _OnnxCrossEncoder(
            TextCrossEncoder(name, threads=_onnx_threads(), enable_cpu_mem_arena=False)
        )

    from langchain_community.cross_encoders import HuggingFaceCrossEncoder

    log.info("Loading cross-encoder: %s", settings.cross_encoder_model)
    return HuggingFaceCrossEncoder(
        model_name=settings.cross_encoder_model,
        model_kwargs={"device": "cpu"},
    )


def unload_model(settings: Settings, model: str) -> bool:
    """Ask Ollama to evict a model from memory immediately.

    Measured motivation, not premature optimisation. Interleaving a 3B
    generator and a 7B judge question-by-question keeps both resident: 7.6 GB
    of models on a 15.6 GB machine, which left ~1.1 GB free and drove the box
    into paging. A full 28-question evaluation had not finished after 57
    minutes. Unloading between phases returned ~8 GB.

    A no-op for hosted providers, and best-effort everywhere: failing to evict
    is a performance problem, never a correctness one, so it never raises.
    """
    if settings.provider != "ollama":
        return False

    import json
    import urllib.error
    import urllib.request

    payload = json.dumps({"model": model, "keep_alive": 0}).encode()
    request = urllib.request.Request(
        f"{settings.ollama_base_url}/api/generate",
        data=payload,
        headers={"Content-Type": "application/json"},
    )
    try:
        with urllib.request.urlopen(request, timeout=30):
            log.info("Unloaded %s", model)
            return True
    except (urllib.error.URLError, OSError) as exc:
        log.warning("Could not unload %s: %s", model, exc)
        return False


def check_backend(settings: Settings, need_judge: bool = False) -> None:
    """Fail fast with an actionable message if the backend is unreachable.

    The original prototype's failure mode for a missing key was a raw traceback
    from deep inside the OpenAI SDK. Checking up front is cheap.
    """
    if settings.embedding_provider == "gemini" and not settings.gemini_api_key:
        raise ProviderError(
            "AURALITH_EMBEDDING_PROVIDER=gemini but GEMINI_API_KEY is not set."
        )
    if settings.provider == "openai":
        if not settings.openai_api_key:
            raise ProviderError("OPENAI_API_KEY is not set.")
        return

    # Hosted generator: the app needs no Ollama at all (embeddings and reranker
    # are local Python). Only the eval judge still lives on Ollama.
    if settings.generator_provider == "gemini":
        if not settings.gemini_api_key:
            raise ProviderError(
                "AURALITH_GENERATOR_PROVIDER=gemini but GEMINI_API_KEY is not set. "
                "Get a free key at aistudio.google.com and put it in .env."
            )
        if not need_judge:
            return

    import urllib.error
    import urllib.request

    try:
        with urllib.request.urlopen(
            f"{settings.ollama_base_url}/api/tags", timeout=5
        ) as resp:
            import json

            names = {m["name"] for m in json.load(resp).get("models", [])}
    except (urllib.error.URLError, OSError) as exc:
        raise ProviderError(
            f"Cannot reach Ollama at {settings.ollama_base_url}. Is `ollama serve` "
            f"running? Original error: {exc}"
        ) from exc

    needed = {settings.judge_model}
    if settings.generator_provider == "ollama":
        needed.add(settings.generator_model)
    missing = needed - names
    if missing:
        raise ProviderError(
            f"Ollama is running but these models are not pulled: {sorted(missing)}. "
            f"Run: {' && '.join(f'ollama pull {m}' for m in sorted(missing))}"
        )
